import numpy as np
import time

def construct():
       start_time = time.time()
       deadline = start_time + 45.0
       
       N = 17
       MIN_DIST = 6
       
       # Quadratic residues mod 17
       Q = {1, 2, 4, 8, 9, 13, 15, 16}
       
       # Generate generator vector g
       # g[i] = 1 if i in Q else 0
       # Note: indices 0..16
       g = np.zeros(17, dtype=np.uint8)
       for q in Q:
           g[q] = 1
           
       # Generate basis: shifts of g
       # The QR code is generated by the circulant matrix.
       # Basis vectors are g, shift(g, 1), ..., shift(g, 8)
       # Actually, the dimension is 9.
       basis = []
       for i in range(9):
           v = np.roll(g, i)
           basis.append(v)
       basis = np.array(basis)
       
       # Generate all 2^9 = 512 codewords
       codewords = []
       for mask in range(512):
           # Compute linear combination
           # mask bits indicate which basis vectors to include
           # Since we are in F2, this is XOR
           w = np.zeros(17, dtype=np.uint8)
           for i in range(9):
               if (mask >> i) & 1:
                   w ^= basis[i]
           
           # Check parity
           if np.sum(w) % 2 == 0:
               # Convert to integer
               val = 0
               for j in range(17):
                   if w[j]:
                       val |= (1 << j)
               codewords.append(val)
               
       # We have 256 codewords
       # Now try to improve with greedy search
       
       # Precompute vectors for fast distance calculation?
       # Or just use bit_count on XOR
       
       selected = set(codewords)
       
       # To find more words, we need to check candidates against all selected.
       # This is O(2^17 * 256). 131072 * 256 ~ 33 million distance checks.
       # Each check is a 17-bit XOR and popcount.
       # In Python, this might be too slow if done in a pure Python loop.
       # We can use NumPy to vectorize the distance check for batches.
       
       # Let's try to add words.
       # We'll iterate through all possible words, check if they are valid.
       # If valid, add to selected.
       
       # To speed up, we can maintain a list of selected vectors.
       # But adding a word invalidates many others.
       
       # Strategy:
       # 1. Start with the 256 linear codewords.
       # 2. Iterate through all 2^17 words.
       # 3. For each word, if not in selected, check distance to all in selected.
       # 4. If min distance >= 6, add to selected.
       
       # This is a greedy "fill" algorithm.
       
       # Optimization:
       # We can break early if time is running out.
       
       # Vectorized distance check:
       # Let S be the set of selected words.
       # For a candidate c, we need min_{s in S} popcount(c XOR s) >= 6.
       
       # We can store S as a numpy array of uint32.
       # For a batch of candidates C, compute distances to all S?
       # C shape (B, 1), S shape (1, K). XOR shape (B, K).
       # Popcount along axis 1. Min along axis 1.
       
       # Memory: B * K * 4 bytes.
       # If K=256, B=1000, memory is 1M floats/ints. Fine.
       
       selected_arr = np.array(list(selected), dtype=np.uint32)
       
       # Iterate through all words
       # We can process in batches.
       
       # Note: The set `selected` changes as we add words.
       # So we need to update `selected_arr`.
       
       # This might be slow if we update the array frequently.
       # But we only add words if they are valid.
       
       # Let's try.
       
       for start in range(0, 1 << N, 1000):
           if time.time() > deadline - 2:
               break
           
           end = min(start + 1000, 1 << N)
           candidates = np.arange(start, end, dtype=np.uint32)
           
           # Filter out already selected
           # This is hard to vectorize with a set.
           # We can just check all, and if it's in selected, skip.
           
           # Compute distances to selected_arr
           # candidates: (B, 1)
           # selected_arr: (1, K)
           
           # To avoid huge memory if K grows large, we might need to be careful.
           # But K starts at 256 and might grow to ~300.
           
           xor = candidates[:, None] ^ selected_arr[None, :]
           # popcount
           # Use bit tricks or numpy
           # numpy doesn't have popcount for uint32 directly in all versions, but we can use unpackbits or just sum bits.
           # Since N=17, we can convert to binary strings? No, too slow.
           # Use: np.unpackbits(xor.astype(np.uint8).reshape(-1, 4), axis=1) -> too complex.
           
           # Simpler: use a helper function for popcount on uint32 array.
           # Or just use Python's int.bit_count if we loop?
           # Looping 1000 * 256 = 256k iterations.
           # 256k * 17 ops ~ 4M ops. Very fast in C, but Python loop overhead is high.
           
           # Let's use a vectorized popcount.
           # xor is uint32.
           # We can split into 4x 8-bit chunks?
           # Or use the fact that N=17.
           
           # Let's just use a precomputed popcount table for 16-bit values?
           # Or use np.bitwise_and with masks.
           
           # Actually, for N=17, we can do:
           # popcount = (xor & 1).sum(axis=1) + ((xor >> 1) & 1).sum(axis=1) ...
           # This is 17 sums.
           
           # Let's try:
           # dists = np.zeros((len(candidates), len(selected_arr)), dtype=np.uint8)
           # for i in range(17):
           #     dists += (xor >> i) & 1
           
           # This is 17 vectorized operations. Should be fast.
           
           dists = np.zeros((len(candidates), len(selected_arr)), dtype=np.uint8)
           for i in range(17):
               dists += (xor >> i) & 1
               
           min_dists = np.min(dists, axis=1)
           
           valid_mask = min_dists >= MIN_DIST
           
           # Get indices of valid candidates
           valid_indices = np.where(valid_mask)[0]
           
           for idx in valid_indices:
               val = int(candidates[idx])
               if val not in selected:
                   selected.add(val)
                   # Update selected_arr
                   # This is O(K) to append to numpy array.
                   selected_arr = np.append(selected_arr, val)
                   
                   # Note: Adding a word makes other candidates potentially invalid.
                   # But we are iterating through candidates in increasing order.
                   # If we add a word, we don't need to re-check previous candidates.
                   # We just need to ensure future candidates are checked against the new set.
                   # Since we recompute `dists` for each batch, and `selected_arr` is updated,
                   # the next batch will see the new word.
                   # However, within the same batch, if we add a word, other candidates in the same batch
                   # might now be invalid.
                   # But we already computed `dists` for the whole batch against the OLD set.
                   # So a candidate might be "valid" against the old set but invalid against the new set (which includes a word added earlier in this batch).
                   # To be safe, we should verify before adding?
                   # Or just accept the slight error?
                   # The error is that we might add a word that is too close to another word added in the same batch.
                   # This would violate the constraint.
                   
                   # So we MUST verify against the CURRENT selected set before adding.
                   # Since the set is small (~300), a Python loop check is fine.
                   
                   # Re-check against all current selected
                   is_valid = True
                   for s in selected:
                       if s == val: continue
                       if (val ^ s).bit_count() < MIN_DIST:
                           is_valid = False
                           break
                   
                   if is_valid:
                       # It was already added to `selected` above?
                       # I added it to `selected` before the check.
                       # Let's restructure.
                       
                       pass
           
           # Restructure the inner loop
           
       return list(selected)
